 79→// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
 80→func (f *FactoryAIDroidAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
 81→	lines, _, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
 82→	if err != nil {
 83→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 84→	}
 85→
 86→	var prompts []string
 87→	for i := range lines {
 88→		if lines[i].Type != transcript.TypeUser {
 89→			continue
 90→		}
 91→		content := transcript.ExtractUserContent(lines[i].Message)
 92→		if content != "" {
 93→			prompts = append(prompts, textutil.StripIDEContextTags(content))
 94→		}
 95→	}
 96→	return prompts, nil
 97→}
