 99→// ExtractSummary extracts the last assistant message as a session summary.
100→func (f *FactoryAIDroidAgent) ExtractSummary(sessionRef string) (string, error) {
101→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
102→	if err != nil {
103→		return "", fmt.Errorf("failed to read transcript: %w", err)
104→	}
105→
106→	lines, parseErr := transcript.ParseFromBytes(data)
107→	if parseErr != nil {
108→		return "", fmt.Errorf("failed to parse transcript: %w", parseErr)
109→	}
110→
111→	for i := len(lines) - 1; i >= 0; i-- {
112→		if lines[i].Type != transcript.TypeAssistant {
113→			continue
114→		}
115→		var msg transcript.AssistantMessage
116→		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
117→			continue
118→		}
119→		for _, block := range msg.Content {
120→			if block.Type == transcript.ContentTypeText && block.Text != "" {
121→				return block.Text, nil
122→			}
123→		}
124→	}
125→	return "", nil
126→}
