257→// --- Transcript flush sentinel ---
258→
259→const stopHookSentinel = "hooks factoryai-droid stop"
260→
261→func waitForTranscriptFlush(transcriptPath string, hookStartTime time.Time) {
262→	const (
263→		maxWait      = 3 * time.Second
264→		pollInterval = 50 * time.Millisecond
265→		tailBytes    = 4096
266→		maxSkew      = 2 * time.Second
267→	)
268→
269→	logCtx := logging.WithComponent(context.Background(), "agent.factoryaidroid")
270→	deadline := time.Now().Add(maxWait)
271→	for time.Now().Before(deadline) {
272→		if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
273→			logging.Debug(logCtx, "transcript flush sentinel found",
274→				slog.Duration("wait", time.Since(hookStartTime)),
275→			)
276→			return
277→		}
278→		time.Sleep(pollInterval)
279→	}
280→	logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
281→		slog.Duration("timeout", maxWait),
282→	)
283→}
284→
285→func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
286→	file, err := os.Open(path) //nolint:gosec // path comes from agent hook input
287→	if err != nil {
288→		return false
289→	}
290→	defer file.Close()
291→
292→	info, err := file.Stat()
293→	if err != nil {
294→		return false
295→	}
296→	offset := info.Size() - tailBytes
297→	if offset < 0 {
298→		offset = 0
299→	}
300→	buf := make([]byte, info.Size()-offset)
301→	if _, err := file.ReadAt(buf, offset); err != nil {
302→		return false
303→	}
304→
305→	lines := strings.Split(string(buf), "\n")
306→	for _, line := range lines {
307→		line = strings.TrimSpace(line)
308→		if line == "" || !strings.Contains(line, stopHookSentinel) {
309→			continue
310→		}
311→
312→		var entry struct {
313→			Timestamp string `json:"timestamp"`
314→		}
315→		if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
316→			continue
317→		}
318→		ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
319→		if err != nil {
320→			ts, err = time.Parse(time.RFC3339, entry.Timestamp)
321→			if err != nil {
322→				continue
323→			}
324→		}
325→		lowerBound := hookStartTime.Add(-maxSkew)
326→		upperBound := hookStartTime.Add(maxSkew)
327→		if ts.After(lowerBound) && ts.Before(upperBound) {
328→			return true
329→		}
330→	}
331→	return false
332→}
