231→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
232→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
233→// Returns a map of agentID -> toolUseID for all spawned agents.
234→func ExtractSpawnedAgentIDs(transcriptLines []TranscriptLine) map[string]string {
235→	agentIDs := make(map[string]string)
236→
237→	for _, line := range transcriptLines {
238→		if line.Type != "user" {
239→			continue
240→		}
241→
242→		// Parse as array of content blocks (tool results)
243→		var contentBlocks []struct {
244→			Type      string          `json:"type"`
245→			ToolUseID string          `json:"tool_use_id"`
246→			Content   json.RawMessage `json:"content"`
247→		}
248→
249→		var msg struct {
250→			Content json.RawMessage `json:"content"`
251→		}
252→		if err := json.Unmarshal(line.Message, &msg); err != nil {
253→			continue
254→		}
255→
256→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
257→			continue
258→		}
259→
260→		for _, block := range contentBlocks {
261→			if block.Type != "tool_result" {
262→				continue
263→			}
264→
265→			// Content can be a string or array of text blocks
266→			var textContent string
267→
268→			// Try as array of text blocks first
269→			var textBlocks []struct {
270→				Type string `json:"type"`
271→				Text string `json:"text"`
272→			}
273→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
274→				var sb strings.Builder
275→				for _, tb := range textBlocks {
276→					if tb.Type == "text" {
277→						sb.WriteString(tb.Text + "\n")
278→					}
279→				}
280→				textContent = sb.String()
281→			} else {
282→				// Try as plain string
283→				var str string
284→				if err := json.Unmarshal(block.Content, &str); err == nil {
285→					textContent = str
286→				}
287→			}
288→
289→			// Look for agentId in the text
290→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
291→				agentIDs[agentID] = block.ToolUseID
292→			}
293→		}
294→	}
295→
296→	return agentIDs
297→}
