322→// CalculateTotalTokenUsageFromTranscript calculates token usage for a turn, including subagents.
323→// It parses the main transcript from startLine, extracts spawned agent IDs,
324→// and calculates their token usage from transcripts in subagentsDir.
325→func CalculateTotalTokenUsageFromTranscript(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
326→	if transcriptPath == "" {
327→		return &agent.TokenUsage{}, nil
328→	}
329→

329→
330→	// Parse transcript once
331→	parsed, _, err := transcript.ParseFromFileAtLine(transcriptPath, startLine)
332→	if err != nil {
333→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
334→	}
335→
336→	// Calculate token usage from parsed transcript
337→	mainUsage := CalculateTokenUsage(parsed)
338→
339→	// Extract spawned agent IDs from the same parsed transcript
340→	agentIDs := ExtractSpawnedAgentIDs(parsed)
341→
342→	// Calculate subagent token usage
343→	if len(agentIDs) > 0 {
344→		subagentUsage := &agent.TokenUsage{}
345→		for agentID := range agentIDs {
346→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
347→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
348→			if err != nil {
349→				// Agent transcript may not exist yet or may have been cleaned up
350→				continue
351→			}
352→			subagentUsage.InputTokens += agentUsage.InputTokens
353→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
354→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
355→			subagentUsage.OutputTokens += agentUsage.OutputTokens
356→			subagentUsage.APICallCount += agentUsage.APICallCount
357→		}
358→		if subagentUsage.APICallCount > 0 {
359→			mainUsage.SubagentTokens = subagentUsage
360→		}
361→	}
362→
363→	return mainUsage, nil
364→}
