 18→// TranscriptLine is an alias to the shared transcript.Line type.
 19→type TranscriptLine = transcript.Line
 20→
 21→// Type aliases for internal use.
 22→type (
 23→	assistantMessage = transcript.AssistantMessage
 24→	toolInput        = transcript.ToolInput
