 27→// droidEnvelope is the top-level structure of a Factory AI Droid JSONL line.
 28→// Droid wraps messages as {"type":"message","id":"...","message":{"role":"assistant","content":[...]}},
 29→// unlike Claude Code which uses {"type":"assistant","uuid":"...","message":{"content":[...]}}.
 30→type droidEnvelope struct {
 31→	Type    string          `json:"type"`
 32→	ID      string          `json:"id"`
 33→	Message json.RawMessage `json:"message"`
 34→}
 35→
 36→// droidMessageRole extracts just the role from the inner message.
 37→type droidMessageRole struct {
 38→	Role string `json:"role"`
 39→}
