 41→// ParseDroidTranscript parses a Droid JSONL file into normalized transcript.Line entries.
 42→// It transforms the Droid envelope format (type="message", role inside message) into the
 43→// shared transcript.Line format (type="assistant"/"user", message=inner content).
 44→// Non-message entries (session_start, etc.) are skipped.
 45→func ParseDroidTranscript(path string, startLine int) ([]transcript.Line, int, error) {
 46→	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
 47→	if err != nil {
 48→		return nil, 0, fmt.Errorf("failed to open transcript: %w", err)
 49→	}
 50→	defer func() { _ = file.Close() }()
 51→
 52→	return parseDroidTranscriptFromReader(file, startLine)
 53→}
