 55→// ParseDroidTranscriptFromBytes parses Droid JSONL content from a byte slice.
 56→func ParseDroidTranscriptFromBytes(content []byte) ([]transcript.Line, error) {
 57→	lines, _, err := parseDroidTranscriptFromReader(bytes.NewReader(content), 0)
 58→	return lines, err
 59→}
