 61→func parseDroidTranscriptFromReader(r io.Reader, startLine int) ([]transcript.Line, int, error) {
 62→	reader := bufio.NewReader(r)
 63→	var lines []transcript.Line
 64→	totalLines := 0
 65→
 66→	for {
 67→		lineBytes, err := reader.ReadBytes('\n')
 68→		if err != nil && err != io.EOF {
 69→			return nil, 0, fmt.Errorf("failed to read transcript: %w", err)
 70→		}
 71→
 72→		if len(lineBytes) == 0 {
 73→			if err == io.EOF {
 74→				break
 75→			}
 76→			continue
 77→		}
 78→
 79→		if totalLines >= startLine {
 80→			if line, ok := parseDroidLine(lineBytes); ok {
 81→				lines = append(lines, line)
 82→			}
 83→		}
 84→		totalLines++
 85→
 86→		if err == io.EOF {
 87→			break
 88→		}
 89→	}
 90→
 91→	return lines, totalLines, nil
 92→}
