 94→// parseDroidLine converts a single Droid JSONL line into a normalized transcript.Line.
 95→// Returns false if the line is not a message entry (e.g., session_start).
 96→func parseDroidLine(lineBytes []byte) (transcript.Line, bool) {
 97→	var env droidEnvelope
 98→	if err := json.Unmarshal(lineBytes, &env); err != nil {
 99→		return transcript.Line{}, false
100→	}
101→
102→	// Only process "message" type entries — skip session_start, etc.
103→	if env.Type != "message" {
104→		return transcript.Line{}, false
105→	}
106→
107→	// Extract role from the inner message
108→	var role droidMessageRole
109→	if err := json.Unmarshal(env.Message, &role); err != nil {
110→		return transcript.Line{}, false
111→	}
112→
113→	return transcript.Line{
114→		Type:    role.Role, // "assistant" or "user"
115→		UUID:    env.ID,
116→		Message: env.Message,
117→	}, true
