228→	return CalculateTokenUsage(lines), nil
229→}
230→
231→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
232→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
233→// Returns a map of agentID -> toolUseID for all spawned agents.
234→func ExtractSpawnedAgentIDs(transcriptLines []TranscriptLine) map[string]string {
235→	agentIDs := make(map[string]string)
236→
237→	for _, line := range transcriptLines {
238→		if line.Type != "user" {
239→			continue
240→		}
241→
242→		// Parse as array of content blocks (tool results)
243→		var contentBlocks []struct {
244→			Type      string          `json:"type"`
245→			ToolUseID string          `json:"tool_use_id"`
246→			Content   json.RawMessage `json:"content"`
247→		}
248→
249→		var msg struct {
250→			Content json.RawMessage `json:"content"`
251→		}
252→		if err := json.Unmarshal(line.Message, &msg); err != nil {
253→			continue
254→		}
255→
256→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
257→			continue
258→		}
259→
260→		for _, block := range contentBlocks {
261→			if block.Type != "tool_result" {
262→				continue
263→			}
264→
265→			// Content can be a string or array of text blocks
266→			var textContent string
267→
268→			// Try as array of text blocks first
269→			var textBlocks []struct {
270→				Type string `json:"type"`
271→				Text string `json:"text"`
272→			}
273→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
274→				var sb strings.Builder
275→				for _, tb := range textBlocks {
276→					if tb.Type == "text" {
277→						sb.WriteString(tb.Text + "\n")
278→					}
279→				}
280→				textContent = sb.String()
281→			} else {
282→				// Try as plain string
283→				var str string
284→				if err := json.Unmarshal(block.Content, &str); err == nil {
285→					textContent = str
286→				}
287→			}
288→
289→			// Look for agentId in the text
290→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
291→				agentIDs[agentID] = block.ToolUseID
292→			}
293→		}
294→	}
295→
296→	return agentIDs
297→}
298→
299→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
300→func extractAgentIDFromText(text string) string {
301→	const prefix = "agentId: "
302→	idx := strings.Index(text, prefix)
303→	if idx == -1 {
304→		return ""
305→	}
306→
307→	// Extract the ID (alphanumeric characters after the prefix)
308→	start := idx + len(prefix)
309→	end := start
310→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
311→		text[end] >= 'A' && text[end] <= 'Z' ||
312→		text[end] >= '0' && text[end] <= '9') {
313→		end++
314→	}
315→
316→	if end > start {
317→		return text[start:end]
318→	}
319→	return ""
320→}
321→
322→// CalculateTotalTokenUsageFromTranscript calculates token usage for a turn, including subagents.
323→// It parses the main transcript from startLine, extracts spawned agent IDs,
324→// and calculates their token usage from transcripts in subagentsDir.
325→func CalculateTotalTokenUsageFromTranscript(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
326→	if transcriptPath == "" {
327→		return &agent.TokenUsage{}, nil
328→	}
329→
330→	// Parse transcript once using Droid-specific parser
331→	parsed, _, err := ParseDroidTranscript(transcriptPath, startLine)
332→	if err != nil {
333→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
334→	}
335→
336→	// Calculate token usage from parsed transcript
337→	mainUsage := CalculateTokenUsage(parsed)
338→
339→	// Extract spawned agent IDs from the same parsed transcript
340→	agentIDs := ExtractSpawnedAgentIDs(parsed)
341→
342→	// Calculate subagent token usage
343→	if len(agentIDs) > 0 {
344→		subagentUsage := &agent.TokenUsage{}
345→		for agentID := range agentIDs {
346→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
347→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
348→			if err != nil {
349→				// Agent transcript may not exist yet or may have been cleaned up
350→				continue
351→			}
352→			subagentUsage.InputTokens += agentUsage.InputTokens
353→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
354→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
355→			subagentUsage.OutputTokens += agentUsage.OutputTokens
356→			subagentUsage.APICallCount += agentUsage.APICallCount
357→		}
358→		if subagentUsage.APICallCount > 0 {
359→			mainUsage.SubagentTokens = subagentUsage
360→		}
361→	}
362→
363→	return mainUsage, nil
364→}
365→
366→// ExtractAllModifiedFilesFromTranscript extracts files modified by both the main agent and
367→// any subagents spawned via the Task tool. It parses the main transcript from
368→// startLine, collects modified files from the main agent, then reads each
369→// subagent's transcript from subagentsDir to collect their modified files too.
370→// The result is a deduplicated list of all modified file paths.
371→func ExtractAllModifiedFilesFromTranscript(transcriptPath string, startLine int, subagentsDir string) ([]string, error) {
372→	if transcriptPath == "" {
373→		return nil, nil
374→	}
375→
376→	// Parse main transcript once using Droid-specific parser
377→	parsed, _, err := ParseDroidTranscript(transcriptPath, startLine)
378→	if err != nil {
379→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
380→	}
381→
382→	// Collect modified files from main agent
383→	fileSet := make(map[string]bool)
384→	var files []string
385→	for _, f := range ExtractModifiedFiles(parsed) {
386→		if !fileSet[f] {
387→			fileSet[f] = true
388→			files = append(files, f)
389→		}
390→	}
391→
392→	// Find spawned subagents and collect their modified files
393→	agentIDs := ExtractSpawnedAgentIDs(parsed)
394→	for agentID := range agentIDs {
395→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
396→		agentLines, _, agentErr := ParseDroidTranscript(agentPath, 0)
397→		if agentErr != nil {
398→			// Subagent transcript may not exist yet or may have been cleaned up
399→			continue
400→		}
401→		for _, f := range ExtractModifiedFiles(agentLines) {
402→			if !fileSet[f] {
403→				fileSet[f] = true
404→				files = append(files, f)
405→			}
406→		}
407→	}
408→
409→	return files, nil
410→}
